            inputs: { input: { quantity: "Dimensionless", unit: "ratio", description: "the signal to scale; 0 when unwired" } },
            outputs: { output: { quantity: "Dimensionless", unit: "ratio", description: "gain times the input" } },
            capabilities: ["gain", "scaling"],
        },
